{
  "steps": [
    {
      "id": 1,
      "claim": "American federalism is the constitutional principle that divides authority between the national (federal) government and the state governments.",
      "evidence": "Standard definition in U.S. political science texts describing federalism as a vertical distribution of power.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The Tenth Amendment states that powers not delegated to the United States nor prohibited to the states are reserved to the states or the people.",
      "evidence": "Text of the Tenth Amendment: “The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.”",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Therefore, the Tenth Amendment directly addresses the allocation of powers between the national government and the states, embodying federalism.",
      "evidence": "Combines the definition of federalism (Step 1) with the reservation of powers in the Tenth Amendment (Step 2).",
      "weight": 0.20,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Option A (checks and balances) describes the horizontal separation of powers among the three branches of the federal government, not the vertical national‑state relationship.",
      "evidence": "Constitutional structure of Articles I‑III; checks and balances pertain to inter‑branch relations within the federal government.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "Option B (international treaty process) is a federal foreign‑policy power and does not illustrate the division of authority between national and state governments.",
      "evidence": "Article II, Section 2 grants treaty‑making power to the President with Senate consent; foreign affairs are exclusively federal.",
      "weight": 0.07,
      "depends_on": []
    },
    {
      "id": 6,
      "claim": "Option C (special status of Washington, D.C.) creates a federal district, a specific administrative arrangement, not a principle governing federal‑state power sharing.",
      "evidence": "Article I, §8, cl. 17 establishes a district under congressional authority; it is an exception, not a structural rule of federalism.",
      "weight": 0.07,
      "depends_on": []
    },
    {
      "id": 7,
      "claim": "Among the four options, only the Tenth Amendment (Option D) directly exemplifies the core concept of American federalism.",
      "evidence": "Steps 1‑3 show the Tenth Amendment embodies the national‑state power split, whereas Steps 4‑6 show the other options do not address that split.",
      "weight": 0.08,
      "depends_on": [1, 2, 3, 4, 5, 6]
    },
    {
      "id": 8,
      "claim": "Therefore, the correct answer is D.",
      "evidence": "Logical conclusion from Step 7.",
      "weight": 0.03,
      "depends_on": [7]
    }
  ],
  "answer": "D",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Describes internal checks among federal branches, not the national‑state power division central to federalism."
    },
    {
      "answer": "B",
      "reason_rejected": "Pertains to foreign‑policy treaty making, unrelated to the federal‑state relationship."
    },
    {
      "answer": "C",
      "reason_rejected": "Relates to the unique constitutional status of the capital district, not to the general principle of power sharing between federal and state governments."
    }
  ]
}
